//! 🧪️ Actual original evaluation receiving preserves typed Dictionary source/cache custody against independent Serde.
use super::*;
use crate::effect::bare;
use semio_os_flow_host_session::evaluation_receiving::*;
use semio_framework_value::RetirementDemand;
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_framework_value::{DslValue, Number};
use semio_framework_value::ToValue;
fn observe<T>(action:impl FnOnce()->T)->(T,(usize,usize)){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(action);(result,(heap.requested_bytes,heap.released_bytes))}
fn dto(value:&serde_json::Value)->DslValue{match value{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(value)=>DslValue::Bool(*value),serde_json::Value::Number(value)=>DslValue::Number(value.as_u64().map(Number::UInt).unwrap_or_else(||Number::Float(value.as_f64().unwrap()))),serde_json::Value::String(value)=>DslValue::String(value.clone()),serde_json::Value::Array(value)=>DslValue::Array(value.iter().map(dto).collect()),serde_json::Value::Object(value)=>DslValue::Object(value.iter().map(|(key,value)|(key.clone(),dto(value))).collect())}}
fn grant(d:RetirementDemand,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn caller()->semio_framework_job::OriginalJobFixtureCaller{crate::effect::source_caller(706)}
#[test]
fn original_completed_preview_evaluation_donates_dictionary_to_actual_original_paid_cache(){
 let fixture:serde_json::Value=serde_json::from_str(read_node("📥️evaluation-source/🔎️read/📨️response/🧪️tests/🧫️fixtures/🧠️dictionary.json")).unwrap();let address=FlowEvaluationReplyAddress{node_hash:u64::MAX,window_id:"original-preview",window_kind_id:"world3d"};
 for body in[1,3,64]{let((source,mut session),heap)=observe(||(dto(&fixture),FlowEvalSession::new()));let mut sums=heap;let mut issuer=caller();
  for turn in 0..1000{let d=RetirementDemand{copy_bytes:session.next_window_tick_latch_copy_byte_demand(address.window_id).unwrap(),capacity_bytes:session.next_window_tick_latch_capacity_byte_demand(address.window_id,64).unwrap(),release_bytes:session.next_window_tick_latch_release_byte_demand(address.window_id).unwrap(),depth:session.next_window_tick_latch_depth_demand(address.window_id).unwrap().max(1)};let((step,heap),p)=bare(&mut issuer,grant(d,64),|cx|observe(||semio_framework_job::close_original_retained_step(cx,d,|g|session.prepare_window_tick_latch_original(address.window_id,g))));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;if turn<4||turn>990{eprintln!("[DEBUG] latch turn={turn} d={d:?} p={p:?} step={:?} fuel={}",step.as_ref().map(|s|s.progress()).map_err(|e|format!("{e:?}")),issuer.fuel_remaining());}if matches!(step.unwrap(),semio_framework_job::InteractiveJobCloseStep::Complete{..}){break}assert!(turn<999)}
  let((mut receiver,heap),p)=bare(&mut issuer,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()},|cx|observe(||FlowEvaluationReplyReceiver::new(source,cx).unwrap_or_else(|_|panic!("original Dictionary reply intake"))));assert_eq!(heap,(0,0));
  for turn in 0..200000{if receiver.terminal_is_empty(){break}assert!(turn<199999);let d=receiver.next_demands(&session,body,address.window_id).unwrap();let g=grant(d,body);let before=receiver.test_diagnostic();
   for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g}),(d.copy_bytes>body).then_some(g),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g})].into_iter().flatten(){let((result,heap),p)=bare(&mut issuer,denied,|cx|observe(||receiver.step(&mut session,&address,cx)));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(p,Default::default());assert_eq!(issuer.fuel_remaining(),1);assert_eq!(receiver.test_diagnostic(),before);}
   let((result,heap),p)=bare(&mut issuer,g,|cx|observe(||receiver.step(&mut session,&address,cx)));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(g));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if d.copy_bytes>body{assert_eq!(p,Default::default());break}
  }
  if body==64{assert!(receiver.terminal_is_empty()&&receiver.test_diagnostic().received);assert_eq!(session.test_evaluation_cache_len(),Some(1));let actual=session.test_inspect_evaluation_cache_original(u64::MAX,ToValue::to_value).unwrap();assert_eq!(actual,dto(&fixture["output"]));}else{assert_eq!(session.test_evaluation_cache_len(),Some(0));}
  issuer.cancel().cancel_now();receiver.begin_close();for turn in 0..200000{if receiver.terminal_is_empty(){break}assert!(turn<199999);let d=receiver.next_close_demands(3).unwrap();let((step,heap),p)=bare(&mut issuer,grant(d,3),|cx|observe(||receiver.close_step(cx)));assert_eq!(step.unwrap().progress(),p);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;}
  session.begin_close();for turn in 0..200000{if session.terminal_is_empty(){break}assert!(turn<199999);let d=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand().unwrap(),capacity_bytes:session.next_close_capacity_byte_demand(3).unwrap(),release_bytes:session.next_close_release_byte_demand().unwrap(),depth:session.next_close_depth_demand().unwrap()};let((step,heap),p)=bare(&mut issuer,grant(d,3),|cx|observe(||semio_framework_job::close_original_effect_step(cx,d,|effect|semio_framework_value::RetainedWorkPoll::Complete(session.retire_source_step(effect)))));assert_eq!(step.unwrap().progress(),p);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));sums.0+=heap.0;sums.1+=heap.1;}
  assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(receiver)).1,(0,0));assert_eq!(observe(||drop(session)).1,(0,0));let stock=issuer.stock();issuer.retire(stock);
 }
}
